def choose_move(observation):
    pos = observation.get('player', {}).get('pos', (0, 0))
    grid = observation.get('grid', [])
    resources = observation.get('resources', [])
    opponents = observation.get('opponents', [])
    goals = observation.get('goals', [])
    territory = observation.get('territory', [])

    def get_closest(targets, p):
        min_dist = float('inf')
        closest = None
        for t in targets:
            dist = abs(p[0] - t[0]) + abs(p[1] - t[1])
            if dist < min_dist:
                min_dist = dist
                closest = t
        return closest

    target_pos = None
    # Pursue nearby opponent if within 3 steps
    for opp in opponents:
        opp_pos = opp.get('pos')
        if opp_pos:
            dist = abs(pos[0] - opp_pos[0]) + abs(pos[1] - opp_pos[1])
            if dist <= 3:
                target_pos = opp_pos
                break
    # Else, seek resources
    if target_pos is None and resources:
        target_pos = get_closest(resources, pos)
    # Else, goals
    if target_pos is None and goals:
        target_pos = get_closest(goals, pos)
    # Else, expand territory
    if target_pos is None and territory:
        target_pos = get_closest(territory, pos)
    # Else, center
    if target_pos is None and grid:
        rows = len(grid)
        cols = len(grid[0]) if grid else 0
        target_pos = (rows // 2, cols // 2)

    delta_x = target_pos[0] - pos[0]
    delta_y = target_pos[1] - pos[1]

    dx = 1 if delta_x > 0 else -1 if delta_x < 0 else 0
    dy = 1 if delta_y > 0 else -1 if delta_y < 0 else 0

    def is_valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) if grid else False

    def attempt_move(dx_candidate, dy_candidate):
        new_x = pos[0] + dx_candidate
        new_y = pos[1] + dy_candidate
        if is_valid(new_x, new_y):
            if grid[new_x][new_y] == 0:
                return [dx_candidate, dy_candidate]
        return None

    move = attempt_move(dx, dy)
    if move:
        return move

    # Try alternatives: rotate directions
    for alt_dx, alt_dy in [(-dy, dx), (dy, -dx), (0, 0)]:
        candidate = attempt_move(alt_dx, alt_dy)
        if candidate:
            return candidate

    return [0, 0]

